std::wstring dataDir;std::vector<uw::data::Conversation>savedChats;std::string currentChatId,pendingDeleteId;bool deleteAfterStop=false,historyDirty=false;std::vector<uw::data::Attachment>pendingAttachments;std::wstring attachmentText;std::vector<std::wstring>pendingFileText;
std::string newId(){GUID id;CoCreateGuid(&id);wchar_t out[64];StringFromGUID2(id,out,64);std::wstring v=out;v.erase(std::remove_if(v.begin(),v.end(),[](wchar_t c){return c=='{'||c=='}';}),v.end());return narrow(v);}
bool validId(const std::string&s){return s.size()==36&&std::all_of(s.begin(),s.end(),[](unsigned char c){return std::isxdigit(c)||c=='-';});}
std::wstring chatFile(const std::string&id){return dataDir+L"\\history\\"+wide(id)+L".json";}
bool atomicText(const std::wstring&path,const std::string&s){auto tmp=path+L".tmp";{std::ofstream out(std::filesystem::path(tmp),std::ios::binary|std::ios::trunc);if(!out)return false;out.write(s.data(),s.size());out.flush();if(!out)return false;}return MoveFileExW(tmp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=FALSE;}
uw::data::Conversation*currentSaved(){for(auto&c:savedChats)if(c.id==currentChatId)return &c;return nullptr;}
void saveCurrent();void loadConversation(const std::string&id);void newConversation();
