void initializeHistory(){auto folder=dataDir+L"\\history";CreateDirectoryW(folder.c_str(),nullptr);CreateDirectoryW((dataDir+L"\\attachments").c_str(),nullptr);std::error_code ec;for(auto&e:std::filesystem::directory_iterator(std::filesystem::path(folder),ec)){if(e.path().extension()!=L".json"||!validId(narrow(e.path().stem().wstring())))continue;try{if(e.file_size()>32*1024*1024)continue;std::ifstream in(e.path(),std::ios::binary);std::string raw((std::istreambuf_iterator<char>(in)),{});auto c=uw::data::parse(raw);if(validId(c.id)&&c.id==narrow(e.path().stem().wstring())){for(auto&m:c.messages)m.attachments.erase(std::remove_if(m.attachments.begin(),m.attachments.end(),[](auto&a){return !ownedAttachment(wide(a.path));}),m.attachments.end());savedChats.push_back(std::move(c));}}catch(...){}}
 std::sort(savedChats.begin(),savedChats.end(),[](auto&a,auto&b){return a.updated>b.updated;});}
bool ownedAttachment(const std::wstring&path){wchar_t full[32768],root[32768];if(!GetFullPathNameW(path.c_str(),32768,full,nullptr))return false;for(auto folder:{L"attachments",L"outputs"}){if(!GetFullPathNameW((dataDir+L"\\"+folder+L"\\").c_str(),32768,root,nullptr))continue;std::wstring prefix=root;if(prefix.back()!=L'\\')prefix+=L'\\';if(_wcsnicmp(full,prefix.c_str(),prefix.size())==0)return true;}return false;}

void removeSaved(const std::string&id){auto found=std::find_if(savedChats.begin(),savedChats.end(),[&](auto&c){return c.id==id;});if(found==savedChats.end())return;for(auto&m:found->messages)for(auto&a:m.attachments){auto path=wide(a.path);if(ownedAttachment(path))DeleteFileW(path.c_str());}DeleteFileW(chatFile(id).c_str());DeleteFileW((chatFile(id)+L".tmp").c_str());savedChats.erase(found);}
void saveAttachmentAs(const std::wstring&path,const std::wstring&name){if(GetFileAttributesW(path.c_str())==INVALID_FILE_ATTRIBUTES){MessageBoxW(mainWindow,L"This file is no longer available.",L"Attachment",MB_OK);return;}wchar_t target[32768];wcsncpy_s(target,name.c_str(),_TRUNCATE);OPENFILENAMEW dialog{};dialog.lStructSize=sizeof(dialog);dialog.hwndOwner=mainWindow;dialog.lpstrFile=target;dialog.nMaxFile=32768;dialog.lpstrFilter=L"All files\0*.*\0";dialog.Flags=OFN_OVERWRITEPROMPT|OFN_PATHMUSTEXIST;if(GetSaveFileNameW(&dialog)&&!CopyFileW(path.c_str(),target,FALSE))MessageBoxW(mainWindow,L"Could not save the file at this location.",L"Save file",MB_OK|MB_ICONERROR);}
std::wstring decodeTextFile(const std::wstring&path){std::ifstream in(std::filesystem::path(path),std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(in)),{});if(bytes.size()>2*1024*1024)throw std::runtime_error("File exceeds the 2 MiB text limit.");if(bytes.size()>=2&&(unsigned char)bytes[0]==0xff&&(unsigned char)bytes[1]==0xfe){std::wstring out;for(size_t i=2;i+1<bytes.size();i+=2)out+=wchar_t((unsigned char)bytes[i]|((unsigned char)bytes[i+1]<<8));return out;}if(bytes.size()>=3&&bytes.substr(0,3)=="\xef\xbb\xbf")bytes.erase(0,3);if(bytes.find('\0')!=std::string::npos)throw std::runtime_error("Binary content requires a document text filter.");return wide(bytes);}
std::wstring filterDocument(const std::wstring&path){using Load=HRESULT(WINAPI*)(LPCWSTR,IUnknown*,void**);HMODULE dll=LoadLibraryW(L"query.dll");if(!dll)throw std::runtime_error("Document text extraction is unavailable.");auto load=(Load)(void*)GetProcAddress(dll,"LoadIFilter");IFilter*filter=nullptr;if(!load||FAILED(load(path.c_str(),nullptr,(void**)&filter))){FreeLibrary(dll);throw std::runtime_error("No installed text reader supports this format. Try TXT, Markdown, CSV or an image.");}ULONG flags=0;std::wstring result;HRESULT hr=filter->Init(IFILTER_INIT_CANON_PARAGRAPHS|IFILTER_INIT_CANON_HYPHENS|IFILTER_INIT_CANON_SPACES|IFILTER_INIT_APPLY_INDEX_ATTRIBUTES,0,nullptr,&flags);if(SUCCEEDED(hr)){STAT_CHUNK chunk{};while(SUCCEEDED(filter->GetChunk(&chunk))){if(!(chunk.flags&CHUNK_TEXT))continue;for(;;){wchar_t part[4096];ULONG count=4096;hr=filter->GetText(&count,part);if(SUCCEEDED(hr))result.append(part,count);if(result.size()>96000){filter->Release();FreeLibrary(dll);throw std::runtime_error("Extracted document text is too large. Split the file first.");}if(hr!=S_OK)break;}result+=L"\n";}}filter->Release();FreeLibrary(dll);if(result.find_first_not_of(L" \r\n\t")==std::wstring::npos)throw std::runtime_error("No text could be extracted. Scanned documents need OCR or image upload.");return result;}
void attachFile(const std::wstring&source){try{if(pendingAttachments.size()>=4)throw std::runtime_error("Attach at most four files per message.");auto path=std::filesystem::path(source);auto ext=path.extension().wstring();std::transform(ext.begin(),ext.end(),ext.begin(),::towlower);bool image=ext==L".png"||ext==L".jpg"||ext==L".jpeg"||ext==L".gif"||ext==L".bmp"||ext==L".webp";std::error_code ec;auto size=std::filesystem::file_size(path,ec);if(ec||size>20*1024*1024)throw std::runtime_error("File is unavailable or exceeds 20 MiB.");std::wstring extracted;if(!image){std::wstring textExt=L".txt .md .csv .json .log .xml .html .htm .cpp .c .h .hpp .py .js .ts .css .yaml .yml .ini .toml .tex .svg";if(textExt.find(ext)!=std::wstring::npos&&!ext.empty())extracted=decodeTextFile(source);else extracted=filterDocument(source);if(extracted.size()>48000||attachmentText.size()+extracted.size()>96000)throw std::runtime_error("Attached text is too large. Split the file first.");}else{Bitmap probe(source.c_str());if(probe.GetLastStatus()!=Ok||!probe.GetWidth()||!probe.GetHeight()||(uint64_t)probe.GetWidth()*probe.GetHeight()>40000000)throw std::runtime_error("This image format is not supported by the installed image decoder.");}
 std::wstring saved=dataDir+L"\\attachments\\"+wide(newId())+ext;if(!CopyFileW(source.c_str(),saved.c_str(),TRUE))throw std::runtime_error("Could not copy the attachment.");pendingAttachments.push_back({narrow(path.filename().wstring()),narrow(saved),image});pendingFileText.push_back(image?L"":L"\n\n--- Attached file: "+path.filename().wstring()+L" ---\n"+extracted+L"\n--- End attachment ---\n");attachmentText.clear();for(auto&t:pendingFileText)attachmentText+=t;InvalidateRect(mainWindow,nullptr,FALSE);
 }catch(const std::exception&e){MessageBoxW(mainWindow,wide(e.what()).c_str(),L"Attach file",MB_OK|MB_ICONINFORMATION);}}
void chooseAttachments(){wchar_t files[65536]{};OPENFILENAMEW dialog{};dialog.lStructSize=sizeof(dialog);dialog.hwndOwner=mainWindow;dialog.lpstrFile=files;dialog.nMaxFile=65536;dialog.lpstrFilter=L"Images and files\0*.*\0";dialog.Flags=OFN_FILEMUSTEXIST|OFN_PATHMUSTEXIST|OFN_ALLOWMULTISELECT|OFN_EXPLORER;if(!GetOpenFileNameW(&dialog))return;std::wstring first=files;auto*next=files+first.size()+1;if(!*next)attachFile(first);else while(*next){std::wstring name=next;attachFile(first+L"\\"+name);next+=name.size()+1;}}
std::string createOutput(const uw::Json&args,const std::string&context){auto name=args.at("filename").str,content=args.at("content").str;if(!uw::data::safeOutputName(name))throw std::runtime_error("Use a plain filename without a directory.");auto ext=std::filesystem::path(wide(name)).extension().wstring();std::transform(ext.begin(),ext.end(),ext.begin(),::towlower);auto extension=narrow(ext);if(!uw::exports::supported(extension))throw std::runtime_error("Supported outputs: DOCX, PDF, PPTX, XLSX, RTF, PNG, JPG/JPEG, BMP, TIFF, ZIP, TXT, Markdown, CSV/TSV, HTML, SVG, JSON/XML and source code. Use modern .docx/.pptx/.xlsx, not legacy .doc/.ppt/.xls.");if(content.size()>2*1024*1024)throw std::runtime_error("Input exceeds 2 MiB.");auto bytes=uw::exports::generate(extension,content);if(bytes.size()>48*1024*1024)throw std::runtime_error("Generated file exceeds 48 MiB.");auto root=dataDir+L"\\outputs";CreateDirectoryW(root.c_str(),nullptr);auto attributes=GetFileAttributesW(root.c_str());if(attributes==INVALID_FILE_ATTRIBUTES||(attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("Output directory is unavailable or redirected.");auto leaf=wide(newId())+L"_"+wide(name),path=root+L"\\"+leaf;if(!atomicText(path,bytes))throw std::runtime_error("Could not save output file.");std::string metadata="{\"name\":"+uw::chat::quote(name)+",\"path\":"+uw::chat::quote(narrow(path))+",\"image\":"+(uw::exports::raster(extension)?"true":"false")+"}";publishChat({uw::chat::Event::File,metadata,context});return "Saved successfully. Download link: ["+name+"](widget-output:"+narrow(leaf)+")";}
void saveCodeFile(const std::wstring&content,const std::wstring&language){std::wstring ext=language==L"python"?L".py":language==L"cpp"?L".cpp":language==L"json"?L".json":language==L"csv"?L".csv":language==L"html"?L".html":L".txt";std::wstring name=L"code"+ext;std::string payload="{\"filename\":"+uw::chat::quote(narrow(name))+",\"content\":"+uw::chat::quote(narrow(content))+"}";try{auto result=createOutput(uw::Parser(payload).parse(),currentChatId);auto marker=result.find("widget-output:");auto end=result.rfind(')');auto path=dataDir+L"\\outputs\\"+wide(result.substr(marker+14,end-marker-14));saveAttachmentAs(path,name);}catch(const std::exception&e){MessageBoxW(mainWindow,wide(e.what()).c_str(),L"Save code",MB_OK|MB_ICONERROR);}}
